"""Satış CSV'sindeki alanları çözümler."""
from datetime import date


def tutar(metin):
    """Türkçe biçimli tutarı sayıya çevirir: "32.500" -> 32500.0, "89,90" -> 89.90."""
    metin = metin.strip()

    # Virgül varsa ondalık ayırıcı, nokta binlik ayırıcı
    if "," in metin:
        tam, kurus = metin.split(",")
        # Noktalardan (binlik ayırıcı) arındır
        return float(tam.replace(".", "")) + float(kurus) / 100
    else:
        # Virgül yoksa, noktaları (binlik ayırıcı) kaldır
        return float(metin.replace(".", ""))


def tarih(metin):
    """"GG.AA.YYYY" biçimindeki tarihi date nesnesine çevirir."""
    a, g, y = metin.strip().split(".")
    return date(int(y), int(a), int(g))

